 5	final class AdjacencyListGraph implements MutableGraph {
 6	    private final List<List<Integer>> adjacencyList;
 7	    private final List<List<Integer>> adjacencyViews;
 8	
 9	    AdjacencyListGraph(int vertexCount) {
10	        if (vertexCount < 0) {
11	            throw new IllegalArgumentException("Vertex count cannot be negative.");
12	        }
13	
14	        adjacencyList = new ArrayList<>(vertexCount);
15	        adjacencyViews = new ArrayList<>(vertexCount);
16	        for (int vertex = 0; vertex < vertexCount; vertex++) {
17	            List<Integer> neighbors = new ArrayList<>();
18	            adjacencyList.add(neighbors);
19	            adjacencyViews.add(Collections.unmodifiableList(neighbors));
20	        }
21	    }
22	
23	    @Override
24	    public int vertexCount() {
25	        return adjacencyList.size();
26	    }
27	
28	    @Override
29	    public void addUndirectedEdge(int from, int to) {
30	        validateVertex(from);
31	        validateVertex(to);
32	
33	        addDirectedEdge(from, to);
34	        addDirectedEdge(to, from);
35	    }
36	
37	    @Override
38	    public List<Integer> neighborsOf(int vertex) {
39	        validateVertex(vertex);
40	        return adjacencyViews.get(vertex);
41	    }
42	
43	    private void addDirectedEdge(int from, int to) {
44	        adjacencyList.get(from).add(to);
45	    }
46	
47	    private void validateVertex(int vertex) {
48	        if (vertex < 0 || vertex >= adjacencyList.size()) {
49	            throw new IllegalArgumentException("Vertex out of range: " + vertex);
50	        }
51	    }
52	}

